"""``listoutputs`` -- list Gkeyll filename stems found in a directory."""

from __future__ import annotations

import click

import postgkyl as pg


@click.command("listoutputs")
@click.option("--extensions", "-e", default="bp,gkyl",
    help="Comma-separated output file extension(s).")
@click.option("--path", "-p", default=".", help="Directory to search for outputs.")
@click.pass_context
def command(ctx, extensions, path) -> None:
  """List the Gkeyll filename stems (per extension) found in a directory."""
  stems_by_ext = pg.diagnostics.discovery.find_output_stems(extensions, path)
  for ext, stems in stems_by_ext.items():
    if stems:
      click.echo(f"{ext}:")
    # end
    for stem in stems:
      click.echo(f"- {stem}")
# end
    # end
  # end

"""``extractinput`` -- print any input file embedded in compatible BP files."""

from __future__ import annotations

import click

from .._apply import active_datasets
from .._options import use_option


@click.command("extractinput")
@use_option
@click.pass_context
def command(ctx, use) -> None:
  """Extract and print the embedded input file from compatible BP files."""
  pool = active_datasets(ctx)
  if use is not None:
    pool = [d for d in pool if d.tag == use]
  # end
  for d in pool:
    text = d.extract_input()
    click.echo(text if text else "No embedded input file!")
# end
  # end

